import { Link, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";

function Home() {
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const stored = localStorage.getItem("user");
    if (stored) {
      try {
        const userData = JSON.parse(stored);
        if (userData && userData.email) {
          setUser(userData);
        } else {
          localStorage.removeItem("user");
        }
      } catch (e) {
        localStorage.removeItem("user");
      }
    }
  }, []);

  const logout = () => {
    localStorage.removeItem("user");
    setUser(null);
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
      fontFamily: "Arial, sans-serif"
    }}>
      {/* Header */}
      <div style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "20px 40px",
        background: "rgba(255,255,255,0.1)"
      }}>
        <h2 style={{color: "white", margin: 0}}>🩺 AI Health Checker</h2>
        <div>
          {user ? (
            <div style={{display: "flex", alignItems: "center", gap: "15px"}}>
              <span style={{color: "white"}}>Welcome, {user.name}!</span>
              <Link to="/health">
                <button style={{
                  padding: "10px 20px",
                  background: "white",
                  color: "#667eea",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer",
                  fontWeight: "bold"
                }}>Check Symptoms</button>
              </Link>
              <Link to="/history">
                <button style={{
                  padding: "10px 20px",
                  background: "transparent",
                  color: "white",
                  border: "2px solid white",
                  borderRadius: "5px",
                  cursor: "pointer"
                }}>My History</button>
              </Link>
              <button onClick={logout} style={{
                padding: "10px 20px",
                background: "rgba(255,255,255,0.2)",
                color: "white",
                border: "none",
                borderRadius: "5px",
                cursor: "pointer"
              }}>Logout</button>
            </div>
          ) : (
            <div style={{display: "flex", gap: "10px"}}>
              <Link to="/login">
                <button style={{
                  padding: "10px 25px",
                  background: "white",
                  color: "#667eea",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer",
                  fontWeight: "bold"
                }}>Login</button>
              </Link>
              <Link to="/signup">
                <button style={{
                  padding: "10px 25px",
                  background: "transparent",
                  color: "white",
                  border: "2px solid white",
                  borderRadius: "5px",
                  cursor: "pointer"
                }}>Sign Up</button>
              </Link>
            </div>
          )}
        </div>
      </div>

      {/* Hero Section */}
      <div style={{
        textAlign: "center",
        padding: "80px 40px",
        color: "white"
      }}>
        <h1 style={{fontSize: "48px", marginBottom: "20px"}}>
          🩺 AI Health Symptom Checker
        </h1>
        <p style={{fontSize: "20px", maxWidth: "600px", margin: "0 auto 40px", opacity: 0.9}}>
          Get instant health predictions powered by Machine Learning. 
          Describe your symptoms and receive intelligent analysis.
        </p>
        
        {!user && (
          <Link to="/signup">
            <button style={{
              padding: "18px 50px",
              fontSize: "18px",
              background: "white",
              color: "#667eea",
              border: "none",
              borderRadius: "30px",
              cursor: "pointer",
              fontWeight: "bold",
              boxShadow: "0 5px 20px rgba(0,0,0,0.2)"
            }}>
              Get Started - It's Free
            </button>
          </Link>
        )}
        
        {user && (
          <Link to="/health">
            <button style={{
              padding: "18px 50px",
              fontSize: "18px",
              background: "white",
              color: "#667eea",
              border: "none",
              borderRadius: "30px",
              cursor: "pointer",
              fontWeight: "bold",
              boxShadow: "0 5px 20px rgba(0,0,0,0.2)"
            }}>
              Check My Symptoms
            </button>
          </Link>
        )}
      </div>

      {/* Features */}
      <div style={{
        display: "flex",
        justifyContent: "center",
        gap: "30px",
        padding: "40px",
        flexWrap: "wrap"
      }}>
        {[
          {icon: "🤖", title: "AI Powered", desc: "Advanced ML algorithms for accurate predictions"},
          {icon: "⚡", title: "Instant Results", desc: "Get analysis in seconds"},
          {icon: "📊", title: "Track History", desc: "View your past symptom checks"},
          {icon: "🔒", title: "Secure & Private", desc: "Your health data is protected"}
        ].map((feature, idx) => (
          <div key={idx} style={{
            background: "rgba(255,255,255,0.15)",
            padding: "30px",
            borderRadius: "15px",
            width: "200px",
            textAlign: "center",
            color: "white"
          }}>
            <div style={{fontSize: "40px", marginBottom: "15px"}}>{feature.icon}</div>
            <h3 style={{margin: "0 0 10px"}}>{feature.title}</h3>
            <p style={{margin: 0, opacity: 0.8, fontSize: "14px"}}>{feature.desc}</p>
          </div>
        ))}
      </div>

      {/* Footer */}
      <div style={{
        textAlign: "center",
        padding: "30px",
        color: "rgba(255,255,255,0.6)",
        fontSize: "14px"
      }}>
        ⚕️ This is an AI-based tool. Always consult a healthcare professional for medical advice.
      </div>
    </div>
  );
}

export default Home;
